quiz.question:
阅读下面一段用于清洗订单记录的转换逻辑，回答它做了什么处理：

def transform(rows):
    result = []
    for row in rows:
        if not row.get('order_id'):
            continue
        amount = row.get('amount')
        if amount is None or amount < 0:
            amount = 0
        result.append({'order_id': row['order_id'], 'amount': amount})
    return result
